<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import QualityTable from '../components/QualityTable.vue';import {fixed} from '../utils/format';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'原浆配方底稿 '+new Date().toLocaleDateString()})})}function download(id:string,samples=false){act(()=>downloadCsv(id,samples))}</script><template><PageHeading index="05 / 配方归档" title="留住比例、波动假设和复核依据。" note="管理员批准后保存不可变配方与模拟样本快照。合规率是模拟通过数/样本数，不是实际生产认证。"/><Notice :message="error"/><div class="two-col"><section><h2>配方复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待管理员复核'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准配方复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成配方快照</button></div></article></section><section><h2>批准底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED FORMULA RECORD</p><h3>{{r.title}}</h3><p>名义成本{{fixed(r.snapshot.result.lp.nominal_cost)}}元/吨 · 模拟通过{{r.snapshot.result.robustness.passed}}/{{r.snapshot.result.robustness.n_samples}}</p><div class="actions"><button @click="download(r.id)">下载配方 CSV ↓</button><button class="secondary" @click="download(r.id,true)">下载扰动样本</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">质量快照</button></div><QualityTable v-if="expanded===r.id" :rows="r.snapshot.result.lp.qualities"/></article></section></div></template>
